WITH base AS (SELECT *, CASE WHEN quantity >= 7 THEN 'High' WHEN quantity >= 4 THEN 'Medium' ELSE 'Low' END AS quantity_band FROM order_items WHERE unit_price BETWEEN 300 AND 320), agg AS (SELECT CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END AS quantity_bucket, order_id, SUM(quantity) AS total_quantity FROM base GROUP BY CASE WHEN quantity >= 8 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END, order_id) SELECT quantity_bucket, order_id FROM agg ORDER BY quantity_bucket DESC, order_id DESC
